        /// </summary>
        private void ResolveCategoryLinksIfMissing(INFO_Information info, DataTable dt)
        {
            if (dt == null || dt.Rows.Count == 0) return;

            // Kiểm tra: nếu có ít nhất 1 row có CategoryLink thì không cần resolve
            bool hasCategoryLink = dt.Columns.Contains("CategoryLink");
            bool hasParentLink = dt.Columns.Contains("ParentLink");
            bool hasChildLink = dt.Columns.Contains("ChildLink");

            if (hasCategoryLink || hasParentLink || hasChildLink)
            {
                // Có ít nhất 1 loại link, kiểm tra thử giá trị row đầu có rỗng không
                bool allEmpty = true;
                foreach (DataRow r in dt.Rows)
                {
                    string cl = hasCategoryLink ? (r["CategoryLink"] ?? "").ToString().Trim() : "";
                    string pl = hasParentLink ? (r["ParentLink"] ?? "").ToString().Trim() : "";
                    string chl = hasChildLink ? (r["ChildLink"] ?? "").ToString().Trim() : "";
                    if (!string.IsNullOrEmpty(cl) || !string.IsNullOrEmpty(pl) || !string.IsNullOrEmpty(chl))
                    {
                        allEmpty = false;
                        break;
                    }
                }
                if (!allEmpty)
                    return; // Có dữ liệu, không cần resolve
            }

            // Thu thập CategoryID duy nhất
            HashSet<int> uniqueIds = new HashSet<int>();
            foreach (DataRow r in dt.Rows)
            {
                int cid = GetCategoryIdFromRow(r);
                if (cid > 0)
                    uniqueIds.Add(cid);
            }

            if (uniqueIds.Count == 0) return;

            _categoryLinkCache = new Dictionary<int, string>();

            // Thử resolve từng category bằng INFO_Category_GetHomeSections
            // Procedure này nhận @CategoryIds dạng comma-separated và trả CategoryID, CategoryLink, CategoryName
            try
            {
                string catIdsParam = string.Join(",", uniqueIds);
                DataTable catDt = info.GetDataTable(
                    "INFO_Category_GetHomeSections",
                    "@CategoryIds", catIdsParam
                );

                if (catDt != null && catDt.Rows.Count > 0
                    && catDt.Columns.Contains("CategoryID")
                    && catDt.Columns.Contains("CategoryLink"))
                {
                    foreach (DataRow cr in catDt.Rows)
                    {
                        int cid = 0;
                        if (int.TryParse(Convert.ToString(cr["CategoryID"]), out cid) && cid > 0)
                        {
                            string link = (cr["CategoryLink"] ?? "").ToString().Trim().Trim('/');
                            if (!string.IsNullOrEmpty(link) && !_categoryLinkCache.ContainsKey(cid))
                                _categoryLinkCache[cid] = link;
                        }
                    }
                }
            }
            catch
            {
                // INFO_Category_GetHomeSections không support => fallback
            }

            // Fallback: nếu cache vẫn thiếu, thử resolve từng ID bằng INFO_Category_GetByLink
            // (thử truyền @CategoryID thay vì @CategoryLink, nếu SP support)
            if (_categoryLinkCache.Count < uniqueIds.Count)
            {
                foreach (int cid in uniqueIds)
                {
                    if (_categoryLinkCache.ContainsKey(cid)) continue;

                    try
                    {
                        DataTable singleDt = info.GetDataTable(
                            "INFO_Category_GetByLink",
                            "@CategoryID", cid,
                            "@LanguageID", ResManager.CurrentLanguageID
                        );

                        if (singleDt != null && singleDt.Rows.Count > 0
                            && singleDt.Columns.Contains("CategoryLink"))
                        {
                            string link = (singleDt.Rows[0]["CategoryLink"] ?? "").ToString().Trim().Trim('/');
