/// <summary>
/// Nếu SP trả về thiếu CategoryLink thì resolve bằng cách query INFO_Category_GetHomeSections,
/// sau đó add cột CategoryLink vào DataTable gốc và populate dữ liệu.
/// </summary>
private void ResolveCategoryLinksIfMissing(INFO_Information info, DataTable dt)
{
    if (dt == null || dt.Rows.Count == 0) return;

    // Kiểm tra xem có row nào có CategoryLink thật không
    bool hasLinkData = false;
    if (dt.Columns.Contains("CategoryLink"))
    {
        foreach (DataRow r in dt.Rows)
        {
            string val = (r["CategoryLink"] ?? "").ToString().Trim();
            if (!string.IsNullOrEmpty(val))
            {
                hasLinkData = true;
                break;
            }
        }
    }
    if (hasLinkData) return;

    // Thu thập CategoryID duy nhất
    HashSet<int> uniqueIds = new HashSet<int>();
    foreach (DataRow r in dt.Rows)
    {
        int cid = GetCategoryIdFromRow(r);
        if (cid > 0)
            uniqueIds.Add(cid);
    }
    if (uniqueIds.Count == 0) return;

    // Query category info từ DB
    Dictionary<int, string> catLinkMap = new Dictionary<int, string>();

    try
    {
        string catIdsParam = string.Join(",", uniqueIds);
        DataTable catDt = info.GetDataTable(
            "INFO_Category_GetHomeSections",
            "@CategoryIds", catIdsParam
        );

        if (catDt != null && catDt.Rows.Count > 0 && catDt.Columns.Contains("CategoryID"))
        {
            // Xác định tên cột chứa CategoryLink (có thể là CategoryLink hoặc Link)
            string linkCol = catDt.Columns.Contains("CategoryLink") ? "CategoryLink"
                           : catDt.Columns.Contains("Link") ? "Link" : "";

            if (!string.IsNullOrEmpty(linkCol))
            {
                foreach (DataRow cr in catDt.Rows)
                {
                    int cid = 0;
                    if (int.TryParse(Convert.ToString(cr["CategoryID"]), out cid) && cid > 0)
                    {
                        string link = (cr[linkCol] ?? "").ToString().Trim().Trim('/');
                        if (!string.IsNullOrEmpty(link) && !catLinkMap.ContainsKey(cid))
                            catLinkMap[cid] = link;
                    }
                }
            }
        }
    }
    catch
    {
        // INFO_Category_GetHomeSections fail
    }

    // Fallback: thử từng ID riêng lẻ nếu còn thiếu
    if (catLinkMap.Count < uniqueIds.Count)
    {
        foreach (int cid in uniqueIds)
        {
            if (catLinkMap.ContainsKey(cid)) continue;

            try
            {
                DataTable singleDt = info.GetDataTable(
                    "INFO_Category_GetHomeSections",
                    "@CategoryIds", cid.ToString()
                );

                if (singleDt != null && singleDt.Rows.Count > 0 && singleDt.Columns.Contains("CategoryID"))
                {
                    string linkCol = singleDt.Columns.Contains("CategoryLink") ? "CategoryLink"
                                   : singleDt.Columns.Contains("Link") ? "Link" : "";

                    if (!string.IsNullOrEmpty(linkCol))
                    {
                        string link = (singleDt.Rows[0][linkCol] ?? "").ToString().Trim().Trim('/');
                        if (!string.IsNullOrEmpty(link))
                            catLinkMap[cid] = link;
                    }
                }
            }
            catch { }
        }
    }

    if (catLinkMap.Count == 0) return;

    // Add cột CategoryLink vào DataTable gốc nếu chưa có
    if (!dt.Columns.Contains("CategoryLink"))
        dt.Columns.Add("CategoryLink", typeof(string));

    // Populate CategoryLink cho từng dòng
    foreach (DataRow r in dt.Rows)
    {
        int cid = GetCategoryIdFromRow(r);
        if (cid > 0 && catLinkMap.ContainsKey(cid))
        {
            string link = catLinkMap[cid];
            if (!string.IsNullOrEmpty(link))
                r["CategoryLink"] = link;
        }
    }
}

